function update(dt){
 if(!running||paused||gameOver)return;gameTime-=dt;if(gameTime<=0){gameTime=0;updateHud();endTimer();return}
 let forward=down('w','arrowup')||control('up'),back=down('s','arrowdown'),left=down('a','arrowleft')||control('left'),right=down('d','arrowright')||control('right'),boosting=down('shift')||control('boost'),drifting=down(' ')||down('space');
 player.cool=Math.max(0,player.cool-dt);player.stun=Math.max(0,player.stun-dt);player.star=Math.max(0,(player.star||0)-dt);
 drive(player,dt,forward,back,left,right,boosting,drifting);
 botDrive(opponent,dt);
 for(const c of [player,opponent]){c.x=clamp(c.x,-field.w/2+2,field.w/2-2);c.z=clamp(c.z,-field.l/2+2,field.l/2-2)}
 // player / opponent contact
 if(Math.hypot(player.x-opponent.x,player.z-opponent.z)<3.2){let [nx,nz]=norm(player.x-opponent.x,player.z-opponent.z);player.vx+=nx*4;player.vz+=nz*4;opponent.vx-=nx*4;opponent.vz-=nz*4}
 // ball dynamics and car hits
 ball.vy-=12*dt;ball.y+=ball.vy*dt;if(ball.y<ball.r*.78){ball.y=ball.r*.78;ball.vy=Math.abs(ball.vy)*.58;if(Math.abs(ball.vy)<1.1)ball.vy=0}
 ball.vx*=Math.pow(.992,dt*60);ball.vz*=Math.pow(.992,dt*60);ball.x+=ball.vx*dt;ball.z+=ball.vz*dt;ball.spin+=dt*3;
 for(const c of [player,opponent]){let dx=ball.x-c.x,dz=ball.z-c.z,dist=Math.hypot(dx,dz),reach=2.8;if(dist<reach&&ball.y<4){let [nx,nz]=norm(dx,dz),hit=(reach-dist)*10+Math.max(0,c.speed)*.72;ball.vx+=nx*hit+c.vx*.48;ball.vz+=nz*hit+c.vz*.48;ball.vy=Math.max(ball.vy,.8+Math.max(0,c.speed)*.14);if(c===player&&dist<2.1)burst(ball.x,ball.y,ball.z,'#8ff5ff',3,2)}}
 if(ball.x>field.w/2-1||ball.x<-field.w/2+1){ball.x=clamp(ball.x,-field.w/2+1,field.w/2-1);ball.vx*=-.72}
 if(Math.abs(ball.z)>field.l/2+1){if(Math.abs(ball.x)<field.goalW/2&&ball.y<5){score(ball.z<0?'blue':'orange');return}else{ball.z=Math.sign(ball.z)*(field.l/2+1);ball.vz*=-.7}}
 for(const b of boxes){b.spin+=dt*2;if(b.active&&Math.hypot(player.x-b.x,player.z-b.z)<3.1){b.active=false;player.item=items[Math.floor(Math.random()*items.length)];updateHud();showToast('ITEM ACQUIRED!');setTimeout(()=>{b.active=true},6500)}}
 for(const p of projectiles){p.life-=dt;if(p.homing){let target=p.owner==='blue'?opponent:player;let [tx,tz]=norm(target.x-p.x,target.z-p.z);p.vx=lerp(p.vx,tx*27,dt*1.7);p.vz=lerp(p.vz,tz*27,dt*1.7)}p.x+=p.vx*dt;p.z+=p.vz*dt;let target=p.owner==='blue'?opponent:player;if(Math.hypot(p.x-target.x,p.z-target.z)<2.5){target.stun=1.5;target.vx+=p.vx*.2;target.vz+=p.vz*.2;burst(p.x,1,p.z,'#ffe36b',15,6);p.life=0}if(Math.hypot(p.x-ball.x,p.z-ball.z)<2.4){ball.vx+=p.vx*.8;ball.vz+=p.vz*.8;p.life=0}}
 projectiles=projectiles.filter(p=>p.life>0);for(const b of bananas){b.life-=dt;if(Math.hypot(b.x-opponent.x,b.z-opponent.z)<2.1){opponent.stun=2;burst(b.x,.5,b.z,'#ffec70',12,4);b.life=0}if(Math.hypot(b.x-player.x,b.z-player.z)<2.1&&b.owner!=='blue'){player.stun=1.5;b.life=0}}bananas=bananas.filter(b=>b.life>0);
 for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;p.vy-=8*dt}particles=particles.filter(p=>p.life>0);
 camera.x=lerp(camera.x,player.x,dt*2.7);camera.z=lerp(camera.z,player.z,dt*2.7);camera.yaw=angleLerp(camera.yaw,player.yaw,dt*2.5);updateHud();
}
function angleLerp(a,b,t){let d=((b-a+Math.PI*3)%(Math.PI*2))-Math.PI;return a+d*Math.min(1,t)}
function drive(c,dt,forward,back,left,right,boosting,drifting){if(c.stun>0){c.vx*=.96;c.vz*=.96;c.yaw+=dt*2.5;return}let accel=forward?24:back?-14:0;let boostingNow=boosting&&c.boost>0&&forward;if(boostingNow){accel+=30;c.boost=Math.max(0,c.boost-34*dt);if(Math.random()<dt*14)burst(c.x,.5,c.z,'#ffb84e',1,1)}else c.boost=Math.min(100,c.boost+9*dt);if(drifting&&Math.abs(c.speed)>3)c.drift=Math.min(1,c.drift+dt*2);else c.drift=Math.max(0,c.drift-dt*3);let steer=(left?1:0)-(right?1:0);let grip=lerp(2.4,1.15,c.drift);c.yaw+=steer*dt*(1.15+Math.min(Math.abs(c.speed)/13,1.2))*Math.sign(c.speed||1);let fx=Math.sin(c.yaw),fz=-Math.cos(c.yaw);c.vx+=fx*accel*dt;c.vz+=fz*accel*dt;let speed=Math.hypot(c.vx,c.vz);let max=boostingNow?30:20;if(speed>max){c.vx*=max/speed;c.vz*=max/speed}let side=c.vx*Math.cos(c.yaw)+c.vz*Math.sin(c.yaw);c.vx-=Math.cos(c.yaw)*side*Math.min(1,grip*dt);c.vz-=Math.sin(c.yaw)*side*Math.min(1,grip*dt);c.vx*=Math.pow(.984,dt*60);c.vz*=Math.pow(.984,dt*60);c.x+=c.vx*dt;c.z+=c.vz*dt;c.speed=Math.hypot(c.vx,c.vz);c.drift=Math.max(0,c.drift-(drifting?0:dt*1.5));if(c.star>0){c.vx*=1.005;c.vz*=1.005}}
function botDrive(c,dt){let targetX=ball.x,targetZ=ball.z+(ball.z<0?4:-5);if(Math.abs(ball.x)<field.goalW/2&&ball.z<-field.l/2+5){targetX=ball.x;targetZ=ball.z+7}let dx=targetX-c.x,dz=targetZ-c.z,want=Math.atan2(dx,-dz),diff=((want-c.yaw+Math.PI*3)%(Math.PI*2))-Math.PI;c.yaw+=clamp(diff,-dt*2.2,dt*2.2);let f=Math.abs(diff)<1.75;drive(c,dt,f,false,diff<-.08,diff>.08,c.boost>15&&Math.hypot(dx,dz)>16,false);if(c.boost<15)c.boost+=dt*9;if(Math.hypot(dx,dz)<11&&Math.random()<dt*.12&&c.item){c.item=items[0];let fx=Math.sin(c.yaw),fz=-Math.cos(c.yaw);projectiles.push({x:c.x,z:c.z,vx:fx*20,vz:fz*20,life:2,owner:'orange'})}}
const focal=()=>Math.min(W,H)*.92;
function project(x,y,z){let dx=x-camera.x,dz=z-camera.z,s=Math.sin(camera.yaw),co=Math.cos(camera.yaw),side=dx*co+dz*s,depth=dx*s-dz*co; // camera faces local -z
 let camY=5.8,theta=.22,up=(y-camY)*Math.cos(theta)+depth*Math.sin(theta);depth=Math.max(1,depth+10);return{x:W/2+side*focal()/depth,y:H*.51-up*focal()/depth,depth}}
function pathWorld(points,color,width=2,close=false){ctx.beginPath();let started=false;for(const p of points){let q=project(p[0],p[1]||0,p[2]);if(q.depth<2)continue;if(!started){ctx.moveTo(q.x,q.y);started=true}else ctx.lineTo(q.x,q.y)}if(close)ctx.closePath();ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
function polyWorld(points,color,stroke=null){let ps=points.map(p=>project(p[0],p[1],p[2]));if(ps.some(p=>p.depth<2))return;ctx.beginPath();ctx.moveTo(ps[0].x,ps[0].y);for(let i=1;i<ps.length;i++)ctx.lineTo(ps[i].x,ps[i].y);ctx.closePath();ctx.fillStyle=color;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1.5;ctx.stroke()}}
function line(x1,z1,x2,z2,color='#ffffff99',w=1){pathWorld([[x1,.05,z1],[x2,.05,z2]],color,w)}
function drawField(){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#102b48');sky.addColorStop(.52,'#4e8a9b');sky.addColorStop(1,'#b4d7cc');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 // stadium glow and horizon bands
 let horizon=H*.37;let glow=ctx.createRadialGradient(W/2,horizon,10,W/2,horizon,W*.65);glow.addColorStop(0,'#b9efff55');glow.addColorStop(1,'#31547000');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H*.65);
 let outer=[[-field.w/2-8,0,-field.l/2-8],[field.w/2+8,0,-field.l/2-8],[field.w/2+8,0,field.l/2+8],[-field.w/2-8,0,field.l/2+8]];polyWorld(outer,'#213d4a');let ground=[[-field.w/2,0,-field.l/2],[field.w/2,0,-field.l/2],[field.w/2,0,field.l/2],[-field.w/2,0,field.l/2]];polyWorld(ground,'#318a57');
 for(let z=-field.l/2;z<field.l/2;z+=11){if(Math.floor((z+field.l/2)/11)%2===0)polyWorld([[-field.w/2,.01,z],[field.w/2,.01,z],[field.w/2,.01,z+11],[-field.w/2,.01,z+11]],'#ffffff0b')}
 // glowing perimeter and markings
 line(-field.w/2,-field.l/2,field.w/2,-field.l/2,'#d7f6ffcc',2);line(-field.w/2,field.l/2,field.w/2,field.l/2,'#d7f6ffcc',2);line(-field.w/2,-field.l/2,-field.w/2,field.l/2,'#d7f6ffb0',2);line(field.w/2,-field.l/2,field.w/2,field.l/2,'#d7f6ffb0',2);line(-field.w/2,0,field.w/2,0,'#d9f3ff88',1.5);
 let circle=[];for(let i=0;i<=40;i++){let a=i/40*Math.PI*2;circle.push([Math.cos(a)*9,.04,Math.sin(a)*9])}pathWorld(circle,'#d9f3ff88',1.5);let box=field.goalW/2+3;for(let z of [-1,1]){let gz=z*(field.l/2-10);pathWorld([[-box,.04,gz-z*7],[box,.04,gz-z*7],[box,.04,gz+z*7],[-box,.04,gz+z*7]],'#d9f3ff80',1.4)}
 // stadium stands and rails
 polyWorld([[-field.w/2-6,1,-field.l/2-4],[field.w/2+6,1,-field.l/2-4],[field.w/2+6,7,-field.l/2-7],[-field.w/2-6,7,-field.l/2-7]],'#244d63');polyWorld([[-field.w/2-6,1,field.l/2+4],[field.w/2+6,1,field.l/2+4],[field.w/2+6,7,field.l/2+7],[-field.w/2-6,7,field.l/2+7]],'#244d63');
 for(let i=0;i<20;i++){let x=-field.w/2-4+i*(field.w+8)/19;let q=project(x,5,-field.l/2-6);let r=project(x,5,field.l/2+6);ctx.fillStyle=['#ffb454','#38dfff','#eaf6ff','#ff765e'][i%4];for(const p of [q,r]){ctx.beginPath();ctx.arc(p.x,p.y,Math.max(1,Math.min(4,26/p.depth)),0,Math.PI*2);ctx.fill()}}
 // walls and goals
 for(let s of [-1,1]){let z=s*(field.l/2+1);polyWorld([[-field.w/2,0,z],[field.w/2,0,z],[field.w/2,2,z],[-field.w/2,2,z]],'#4d7682');let gz=s*(field.l/2+2);let gw=field.goalW/2;polyWorld([[-gw,0,gz],[gw,0,gz],[gw,6,gz],[-gw,6,gz]],s<0?'#279ac8':'#dd7044');for(let i=0;i<=6;i++){let x=-gw+i*gw/3;line(x,gz,x,gz+s*field.goalD,'#d8f6ff66',1)}for(let i=0;i<=4;i++){let zz=gz+s*i*field.goalD/4;line(-gw,zz,gw,zz,'#d8f6ff66',1)}}
}

